        <div class="dp6-specs__probe"><span class="dp6-specs__probe-type">Konvex</span><span class="dp6-specs__probe-name">SC5-1E</span><span class="dp6-specs__probe-detail">Abdomen, OB/GYN · 1–5 MHz</span></div>
